<?php require_once __DIR__."/../../config/auth.php";require_role(["admin","cashier"]);header("Content-Type: application/json; charset=utf-8");try{$d=json_decode(file_get_contents("php://input"),true);check_csrf($d["csrf"]??"");$items=$d["items"]??[];$session=cash_session();if(!$session)throw new Exception("No open cashier session.");if(!$items)throw new Exception("Cart is empty.");$pdo=db();$pdo->beginTransaction();$sub=0;$clean=[];$g=$pdo->prepare("SELECT * FROM products WHERE id=? AND is_active=1 FOR UPDATE");foreach($items as $x){$g->execute([(int)$x["id"]]);$p=$g->fetch();$q=(float)$x["qty"];if(!$p||$q<=0||$p["stock_qty"]<$q)throw new Exception("Insufficient stock.");$line=$q*$p["sale_price"];$sub+=$line;$clean[]=[$p,$q,$line];}$disc=min($sub,max(0,(float)($d["discount"]??0)));$total=$sub-$disc;$paid=max(0,(float)($d["paid"]??0));$change=max(0,$paid-$total);$pay=in_array($d["payment"]??"cash",["cash","card","other"],true)?$d["payment"]:"cash";$no="RF-".date("YmdHis")."-".random_int(100,999);$s=$pdo->prepare("INSERT INTO invoices(invoice_no,user_id,cash_session_id,subtotal,discount,total,paid,change_amount,payment_method,status) VALUES(?,?,?,?,?,?,?,?,?,?)");$s->execute([$no,user()["id"],$session["id"],$sub,$disc,$total,$paid,$change,$pay,$paid>=$total?"paid":($paid?"partial":"unpaid")]);$iid=$pdo->lastInsertId();$ii=$pdo->prepare("INSERT INTO invoice_items(invoice_id,product_id,product_name,sku,qty,unit_price,line_total) VALUES(?,?,?,?,?,?,?)");$up=$pdo->prepare("UPDATE products SET stock_qty=stock_qty-? WHERE id=?");$mv=$pdo->prepare("INSERT INTO stock_movements(product_id,user_id,type,qty,reference_type,reference_id,note) VALUES(?,?,?,?,?,?,?)");foreach($clean as [$p,$q,$line]){$ii->execute([$iid,$p["id"],$p["name_en"],$p["sku"],$q,$p["sale_price"],$line]);$up->execute([$q,$p["id"]]);$mv->execute([$p["id"],user()["id"],"out",$q,"invoice",$iid,"POS Sale"]);} $pdo->commit();echo json_encode(["ok"=>1,"id"=>$iid]);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();http_response_code(400);echo json_encode(["ok"=>0,"error"=>$e->getMessage()]);}